import numpy as np

# Load GSL library
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLFunction:
    def __init__(self, func):
        self.func = func

    def __call__(self, x):
        return self.func(x)

class CQuadWorkspace:
    def __init__(self, workspace_size):
        self.workspace_size = workspace_size
        self.workspace = np.empty(self.workspace_size, dtype=np.float64)

def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    # Create GSL function
    gsl_function = GSLFunction(func)

    # Create CQuadWorkspace
    cquad_workspace = CQuadWorkspace(workspace_size)

    # Call C function
    result = gsl.gsl_integration_cquad(gsl_function, a, b, epsabs, epsrel, cquad_workspace.workspace)

    # Unpack result
    integral = result.contents.result
    absolute_error = result.contents.abserr
    function_evaluations = result.contents.neval

    return (integral, absolute_error, function_evaluations)

