    return gslcblas, gsl

def process_array(input_array):
    try:
        gslcblas, gsl = load_gsl_library()
        # Define the function prototype for the mathematical operation
        f_ptr = ctypes.CFUNCTYPE(None, ctypes.POINTER(ctypes.c_double), ctypes.c_size_t)(("gsl_function", gsl))
        # Convert the input list to a C-style array and pass it to the function
        c_input = (ctypes.c_double * len(input_array))(*input_array)
        result = f_ptr(c_input, len(input_array))
        # Return the result as a Python list
        return [float(r) for r in result]
    except CFunctionError:
        raise
    except Exception:
        raise CFunctionError("Unexpected error occurred while processing array.")

