    if not isinstance(trim, float) or trim < 0 or trim > 1:
        raise InvalidInputError("Trim factor must be a float between 0 and 1")
    if not isinstance(sorted_data, list) or not all(isinstance(x, float) for x in sorted_data):
        raise InvalidInputError("Sorted data must be a list of floats")
    if not isinstance(stride, int) or stride < 1:
        raise InvalidInputError("Stride must be a positive integer")
    if not isinstance(size, int) or size < 0:
        raise InvalidInputError("Size must be a non-negative integer")

    try:
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so", mode=ctypes.RTLD_GLOBAL)
        gsl_stats_trmean_from_sorted_data = gsl.gsl_stats_trmean_from_sorted_data
        gsl_stats_trmean_from_sorted_data.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.c_size_t]
        gsl_stats_trmean_from_sorted_data.restype = ctypes.c_double
    except OSError as e:
        raise InvalidInputError("Failed to load GSL library") from e

    trimmed_data = sorted_data[stride - 1::stride]
    if len(trimmed_data) < 2:
        raise InvalidInputError("Not enough data to compute trimmed mean")
