        for i in range(n):
            det += matrix[i][i] * pow(-1, i+1) * gsl_determinant_submatrix(matrix, i, n)
        return det

    # Define C function to compute determinant of a submatrix
    def gsl_determinant_submatrix(matrix, i, n):
        submatrix = [[0.0 for _ in range(n-1)] for _ in range(n-1)]
        for row in range(n):
            for col in range(n):
                if row == i or col == i:
                    continue
                submatrix[row-1][col-1] = matrix[row][col]
        return gsl_determinant(submatrix, n-1)

    # Compute determinant of input matrix using GSL C function
    result = gsl_determinant(matrix, len(matrix))

    # Return JSON object with determinant value
    return { "Candidate_solution": f"{result}" }

