class PoissonDistribution(object):
    def __init__(self, mu):
        self.mu = mu
        self.cdf_P = None
        self.cdf_Q = None

    def compute_cdf(self, k):
        if self.mu <= 0:
            return -1

        if k < 0:
            return 0

        if self.cdf_P is None:
            self.cdf_P = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL).gsl_cdf_poisson_P(k, self.mu)

