            self.cdf_Q = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL).gsl_cdf_poisson_Q(k, self.mu)

        return self.cdf_P if k <= self.mu else 1 - self.cdf_Q

    def poisson_cdf_P(self, k):
        return self.compute_cdf(k)

    def poisson_cdf_Q(self, k):
        return 1 - self.compute_cdf(k)

