import numpy as np

def compute_gauss_legendre(n, eps):
    gsl = ctypes.CDLL("libgsl.so")
    gsl_cblas = ctypes.CDLL("libgslcblas.so", mode=ctypes.RTLD_GLOBAL)

    # Define the function to compute the Gauss-Legendre points and weights
    def gauss_legendre_tbl(n, eps):
        return np.array([gsl.gsl_sf_gauss_legendre(i, n, eps) for i in range(1, n+1)])

    # Compute the Gauss-Legendre points and weights
    points = gauss_legendre_tbl(n, eps)
    weights = np.array([gsl_cblas.cblas_dot(points[i], points[i+1]) for i in range(0, n-1)])

    # Return the computed points and weights as a JSON object
    return {"Candidate_solution": json.dumps({"points": points.tolist(), "weights": weights.tolist()})}

