class GslSumLevinUWorkspace:
    def __init__(self):
        self.gsl = None
        self.workspace = None

    def allocate(self, n):
        if not isinstance(n, int) or n <= 0:
            raise ValueError("Invalid input")

        self.gsl = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
