        status = self.gsl.gsl_sum_levin_u_alloc(n, byref(self.workspace))

        if status != 0:
            raise RuntimeError("Failed to allocate workspace")

    def free(self):
        if self.workspace is not None:
            self.gsl.gsl_sum_levin_u_free(self.workspace)

    def get_result(self):
        return np.array(self.workspace[:n])

