import ctypes

class gsl_function(ctypes.Structure):
    _fields_ = [("function", ctypes.CFUNCTYPE(ctypes.c_double, ctypes.POINTER(ctypes.c_double))), ("params", ctypes.c_void_p)]

def func_wrapper(x, params):
    return py_func(*params)

def compute_integral(py_func, a, b, epsabs, epsrel, n):
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)

    # Allocate a Romberg workspace
    work = gsl.gsl_integration_romberg_alloc(n)

    # Define a Python callback function to represent the mathematical function to be integrated and pass it to the 'gsl_integration_romberg' function
    func = gsl_function()
    func.function = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.POINTER(ctypes.c_double))(func_wrapper)
    func.params = ctypes.py_object(py_func)

    # Compute the integral over the specified interval [a, b] with given absolute and relative error tolerances (epsabs, epsrel)
    result = gsl.gsl_integration_romberg(ctypes.byref(func), a, b, epsabs, epsrel, work)

    # Free the allocated workspace using 'gsl_integration_romberg_free'
    gsl.gsl_integration_romberg_free(work)

    return result

