class GslRstatQuantileWorkspace:
    def __init__(self, p):
        self.p = p
        self.workspace = None

    def allocate(self):
        if self.workspace is not None:
            raise ValueError("Quantile workspace already allocated")
        self.workspace = gsl_rstat_quantile_alloc()

    def reset(self):
        if self.workspace is None:
            raise ValueError("Quantile workspace not allocated")
        gsl_rstat_quantile_reset(self.workspace)

    def add(self, values):
        if self.workspace is None:
            raise ValueError("Quantile workspace not allocated")
        for value in values:
            gsl_rstat_quantile_add(self.workspace, value)

    def get(self):
        if self.workspace is None:
            raise ValueError("Quantile workspace not allocated")
        return gsl_rstat_quantile_get(self.workspace, self.p)

    def free(self):
        if self.workspace is not None:
            gsl_rstat_quantile_free(self.workspace)
            self.workspace = None

